from common import *
from analyze_r02 import rows
import numpy as np,math
from shapely.geometry import LineString,Point

def analyze(out):
 runtime=read(out/'runtime.json');spec=read(out/'spec.json');cfg=read(out/'mission.json');mission=read(out/'mission_result.json') if (out/'mission_result.json').exists() else {};checks=dict(runtime_clean=runtime['passed'],original_database_unchanged=runtime['original_db_unchanged'],selected_route_completed=mission.get('passed',False));truth=rows(out/'evaluation/truth.jsonl');xy=np.array([x['xyz'][:2] for x in truth]);times=np.array([x['t'] for x in truth]);line=LineString(np.array(cfg['route_world'])[:,:2]);cross=[line.distance(Point(p)) for p in xy];progress=[line.project(Point(p)) for p in xy];refs=rows(out/'reference/reference.jsonl');errors=[]
 for row in refs:
  if row.get('valid') and 'pose' in row:errors.append(math.dist(np.array(row['pose'][:2])+[28,14],[np.interp(row['odom_t'],times,xy[:,j]) for j in range(2)]))
 rmse=float(np.sqrt(np.mean(np.square(errors)))) if errors else None;contacts=read(out/'evaluation/contacts.json');bad={k:v for k,v in contacts.items() if 'vehicle::' in k and not ('wheel::' in k and 'ground::body::ground' in k)};checks.update(no_unexpected_contact=not bad,map_rmse_under_15cm=rmse is not None and rmse<.15,cross_track_under_50cm=bool(cross) and max(cross)<.5,measured_progress=bool(progress) and max(progress)>=mission.get('selected_length_m',1e6)-.25,stopped=bool(mission.get('final_gate',{}).get('stopped')))
 owners=mission.get('ownership',{});checks.update(unique_actuator=owners.get('/s03/actuator/request')==['r08_actuator_gate'],no_tool_owner=owners.get('/s10/tool/command')==[],unique_tf=set(owners.get('/tf',[]))=={'s05_local_odometry','s08_global_pose_manager'} and len(owners.get('/tf',[]))==2,source_binding=all((ROOT/p).is_file() and sha(ROOT/p)==h for p,h in spec['implementation_bindings'].items()),task_version=cfg['version']==read(edition('R08')/'mission.json')['version'])
 decisions=rows(out/'decisions.jsonl');actions=[x.get('action',x.get('selected_action')) for x in decisions];events=rows(out/'mission_events.jsonl');tracks=rows(out/'tracking/tracks.jsonl');follow=[x for x in decisions if x.get('action')=='FOLLOW'];gaps=[x['evidence']['clearance_m'] for x in follow if 'clearance_m' in x.get('evidence',{})]
 if spec['case']=='leader':checks.update(observed_follow=bool(gaps) and min(gaps)>=2.,stop_resume=any(x['event']=='BT_INTERRUPTS_PATH' for x in events) and any(x['event']=='RESUME_REMAINING_ROUTE' for x in events),tracking_no_fixture=all(not x.get('truth_used',True) for x in tracks))
 result=dict(passed=all(checks.values()),checks=checks,case=spec['case'],task_result=mission,map_xy_rmse_m=rmse,maximum_cross_track_m=max(cross) if cross else None,maximum_actual_progress_m=max(progress) if progress else 0,follow_decisions=len(follow),minimum_observed_follow_gap_m=min(gaps) if gaps else None,unexpected_contacts=bad,full_connector_passed=bool(mission.get('full_route_selected') and all(checks.values())),formal_credit=False,scope='Selected inspection route only; full R08 additionally requires all declared behavior cases');dump(out/'analysis_r08.json',result);np.savez(out/'trajectory.npz',xy=xy,t=times);return result
